const profile = $('Build Final Dataset Profile').first().json;
const intelligence = $('Parse Dataset Intelligence').first().json;

// --------------------------------------------------
// Helpers
// --------------------------------------------------

function sqlString(value) {
  if (value === null || value === undefined) {
    return 'NULL';
  }

  return `'${String(value).replace(/'/g, "''")}'`;
}

function sqlJson(value) {
  const json = JSON.stringify(value ?? null);
  return `${sqlString(json)}::jsonb`;
}

function sqlNumber(value) {
  if (value === null || value === undefined || value === '') {
    return 'NULL';
  }

  const number = Number(value);

  return Number.isFinite(number)
    ? String(number)
    : 'NULL';
}

function sqlBoolean(value) {
  return value === true ? 'TRUE' : 'FALSE';
}

// --------------------------------------------------
// Validate required data
// --------------------------------------------------

if (!profile) {
  throw new Error('Build Final Dataset Profile returned no data');
}

if (!profile.dataset_id) {
  throw new Error('Final dataset profile is missing dataset_id');
}

if (!intelligence) {
  throw new Error('Parse Dataset Intelligence returned no data');
}

// Defensive arrays
const columnProfiles = Array.isArray(profile.column_profiles)
  ? profile.column_profiles
  : [];

const intelligenceColumns = Array.isArray(intelligence.columns)
  ? intelligence.columns
  : [];

const candidateMetrics = Array.isArray(intelligence.candidate_metrics)
  ? intelligence.candidate_metrics
  : [];

const cleaningLog = Array.isArray(profile.cleaning_log)
  ? profile.cleaning_log
  : [];

const cleaningSuggestions = Array.isArray(
  intelligence.cleaning_suggestions
)
  ? intelligence.cleaning_suggestions
  : [];

const qualityIssues = Array.isArray(profile.quality_issues)
  ? profile.quality_issues
  : [];

// --------------------------------------------------
// Semantic metadata lookup
// --------------------------------------------------

const semanticByColumn = {};

for (const column of intelligenceColumns) {
  if (!column || !column.column_name) continue;

  semanticByColumn[column.column_name] = column;
}

// --------------------------------------------------
// SQL statements
// --------------------------------------------------

const statements = [];

// --------------------------------------------------
// Ensure supporting tables exist
// --------------------------------------------------

statements.push(`
CREATE TABLE IF NOT EXISTS public.dealos_dataset_columns (
  dataset_id uuid NOT NULL
    REFERENCES public.dealos_datasets(id)
    ON DELETE CASCADE,

  column_name text NOT NULL,
  original_name text,
  detected_type text,

  semantic_role text,
  business_meaning text,
  role_confidence text,

  null_pct numeric,

  unique_count bigint,
  unique_count_capped boolean DEFAULT true,

  min_value numeric,
  max_value numeric,
  mean_value numeric,

  sample_values jsonb NOT NULL DEFAULT '[]'::jsonb,

  PRIMARY KEY (dataset_id, column_name)
);
`);

statements.push(`
CREATE TABLE IF NOT EXISTS public.dealos_dataset_metrics (
  id bigserial PRIMARY KEY,

  dataset_id uuid NOT NULL
    REFERENCES public.dealos_datasets(id)
    ON DELETE CASCADE,

  metric_name text NOT NULL,
  metric_type text,

  source_columns jsonb NOT NULL DEFAULT '[]'::jsonb,

  formula_description text,

  confidence text,

  requires_confirmation boolean NOT NULL DEFAULT true,
  is_approved boolean NOT NULL DEFAULT false,

  created_at timestamptz NOT NULL DEFAULT now()
);
`);

statements.push(`
CREATE TABLE IF NOT EXISTS public.dealos_cleaning_log (
  id bigserial PRIMARY KEY,

  dataset_id uuid NOT NULL
    REFERENCES public.dealos_datasets(id)
    ON DELETE CASCADE,

  action text NOT NULL,
  column_name text,

  details jsonb,

  rows_affected integer,

  automatic boolean NOT NULL DEFAULT true,

  created_at timestamptz NOT NULL DEFAULT now()
);
`);

statements.push(`
CREATE TABLE IF NOT EXISTS public.dealos_quality_issues (
  id bigserial PRIMARY KEY,

  dataset_id uuid NOT NULL
    REFERENCES public.dealos_datasets(id)
    ON DELETE CASCADE,

  issue_type text NOT NULL,

  column_name text,

  severity text,

  details text,

  status text NOT NULL DEFAULT 'open',

  created_at timestamptz NOT NULL DEFAULT now()
);
`);

// --------------------------------------------------
// Update main dataset record
// --------------------------------------------------

statements.push(`
UPDATE public.dealos_datasets
SET
  row_count_raw =
    ${sqlNumber(profile.row_count_raw)},

  row_count_clean =
    ${sqlNumber(profile.row_count_clean)},

  column_count =
    ${sqlNumber(profile.column_count)},

  quality_score =
    ${sqlNumber(profile.quality_score)},

  domain =
    ${sqlString(intelligence.domain ?? 'Unknown')},

  grain_description =
    ${sqlString(
      intelligence.grain?.description ?? ''
    )},

  grain_confidence =
    ${sqlString(
      intelligence.grain?.confidence ?? 'low'
    )},

  status = 'ready',

  profile_json =
    ${sqlJson(profile.profile_for_ai ?? profile)}

WHERE id =
  ${sqlString(profile.dataset_id)}::uuid;
`);

// --------------------------------------------------
// Replace column metadata
// --------------------------------------------------

statements.push(`
DELETE FROM public.dealos_dataset_columns
WHERE dataset_id =
  ${sqlString(profile.dataset_id)}::uuid;
`);

for (const column of columnProfiles) {

  if (!column || !column.column_name) {
    continue;
  }

  const semantic =
    semanticByColumn[column.column_name] ?? {};

  statements.push(`
INSERT INTO public.dealos_dataset_columns (
  dataset_id,

  column_name,
  original_name,

  detected_type,

  semantic_role,
  business_meaning,
  role_confidence,

  null_pct,

  unique_count,
  unique_count_capped,

  min_value,
  max_value,
  mean_value,

  sample_values
)
VALUES (
  ${sqlString(profile.dataset_id)}::uuid,

  ${sqlString(column.column_name)},
  ${sqlString(column.original_name)},

  ${sqlString(column.detected_type ?? 'unknown')},

  ${sqlString(
    semantic.semantic_role ?? 'unknown'
  )},

  ${sqlString(
    semantic.business_meaning ?? ''
  )},

  ${sqlString(
    semantic.confidence ?? 'low'
  )},

  ${sqlNumber(column.null_pct)},

  ${sqlNumber(column.unique_count)},

  ${sqlBoolean(
    column.unique_count_capped !== false
  )},

  ${sqlNumber(column.min_value)},
  ${sqlNumber(column.max_value)},
  ${sqlNumber(column.mean_value)},

  ${sqlJson(column.sample_values ?? [])}
);
`);
}

// --------------------------------------------------
// Replace candidate metrics
// --------------------------------------------------

statements.push(`
DELETE FROM public.dealos_dataset_metrics
WHERE dataset_id =
  ${sqlString(profile.dataset_id)}::uuid;
`);

for (const metric of candidateMetrics) {

  if (!metric || !metric.metric_name) {
    continue;
  }

  const requiresConfirmation =
    metric.requires_confirmation !== false;

  statements.push(`
INSERT INTO public.dealos_dataset_metrics (
  dataset_id,

  metric_name,
  metric_type,

  source_columns,

  formula_description,

  confidence,

  requires_confirmation,
  is_approved
)
VALUES (
  ${sqlString(profile.dataset_id)}::uuid,

  ${sqlString(metric.metric_name)},

  ${sqlString(
    metric.metric_type ?? 'unknown'
  )},

  ${sqlJson(metric.source_columns ?? [])},

  ${sqlString(
    metric.formula_description ?? ''
  )},

  ${sqlString(
    metric.confidence ?? 'low'
  )},

  ${sqlBoolean(requiresConfirmation)},

  ${sqlBoolean(!requiresConfirmation)}
);
`);
}

// --------------------------------------------------
// Replace automatic cleaning log
// --------------------------------------------------

statements.push(`
DELETE FROM public.dealos_cleaning_log
WHERE dataset_id =
  ${sqlString(profile.dataset_id)}::uuid;
`);

for (const action of cleaningLog) {

  if (!action || !action.action) {
    continue;
  }

  statements.push(`
INSERT INTO public.dealos_cleaning_log (
  dataset_id,

  action,

  column_name,

  details,

  rows_affected,

  automatic
)
VALUES (
  ${sqlString(profile.dataset_id)}::uuid,

  ${sqlString(action.action)},

  ${sqlString(action.column_name ?? null)},

  ${sqlJson(action)},

  ${sqlNumber(action.rows_affected ?? 0)},

  ${sqlBoolean(action.automatic !== false)}
);
`);
}

// --------------------------------------------------
// Add AI cleaning suggestions
// --------------------------------------------------

for (const suggestion of cleaningSuggestions) {

  if (!suggestion) {
    continue;
  }

  statements.push(`
INSERT INTO public.dealos_cleaning_log (
  dataset_id,

  action,

  column_name,

  details,

  rows_affected,

  automatic
)
VALUES (
  ${sqlString(profile.dataset_id)}::uuid,

  'suggested_cleaning',

  ${sqlString(
    suggestion.column_name ?? null
  )},

  ${sqlJson(suggestion)},

  0,

  FALSE
);
`);
}

// --------------------------------------------------
// Replace quality issues
// --------------------------------------------------

statements.push(`
DELETE FROM public.dealos_quality_issues
WHERE dataset_id =
  ${sqlString(profile.dataset_id)}::uuid;
`);

for (const issue of qualityIssues) {

  if (!issue) {
    continue;
  }

  statements.push(`
INSERT INTO public.dealos_quality_issues (
  dataset_id,

  issue_type,

  column_name,

  severity,

  details,

  status
)
VALUES (
  ${sqlString(profile.dataset_id)}::uuid,

  ${sqlString(
    issue.issue_type ?? 'unknown'
  )},

  ${sqlString(
    issue.column_name ?? null
  )},

  ${sqlString(
    issue.severity ?? 'low'
  )},

  ${sqlString(
    issue.details ?? ''
  )},

  'open'
);
`);
}

// --------------------------------------------------
// Return SQL
// --------------------------------------------------

return [
  {
    json: {
      dataset_id: profile.dataset_id,

      row_count_raw:
        profile.row_count_raw ?? 0,

      row_count_clean:
        profile.row_count_clean ?? 0,

      column_count:
        profile.column_count ?? 0,

      quality_score:
        profile.quality_score ?? null,

      domain:
        intelligence.domain ?? 'Unknown',

      sql: statements.join('\n')
    }
  }
];

const profile = $('Build Final Dataset Profile').first().json;
const i = $('Parse Dataset Intelligence').first().json;

return [{
  json: {
    success: true,

    dataset: {
      id: profile.dataset_id,
      name: profile.dataset_name,
      original_filename: profile.original_filename,
      row_count_raw: profile.row_count_raw ?? 0,
      row_count_clean: profile.row_count_clean ?? 0,
      column_count: profile.column_count ?? 0,
      quality_score: profile.quality_score ?? null,
      domain: i?.domain ?? 'Unknown',
      grain: i?.grain ?? {
        description: '',
        confidence: 'low'
      }
    },

    detected: {
      columns: Array.isArray(i?.columns)
        ? i.columns
        : [],

      metrics: Array.isArray(i?.candidate_metrics)
        ? i.candidate_metrics
        : [],

      dimensions: Array.isArray(i?.dimensions)
        ? i.dimensions
        : [],

      time_fields: Array.isArray(i?.time_fields)
        ? i.time_fields
        : []
    },

    cleaning: {
      automatic_actions: Array.isArray(profile?.cleaning_log)
        ? profile.cleaning_log
        : [],

      suggested_actions: Array.isArray(i?.cleaning_suggestions)
        ? i.cleaning_suggestions
        : [],

      quality_issues: Array.isArray(profile?.quality_issues)
        ? profile.quality_issues
        : []
    },

    sample_rows: [],

    next: {
      analyze_endpoint: '/webhook/dealos-analyze',
      suggested_question:
        'Give me a general overview of this dataset, including the most important metrics, trends, segments, anomalies, and data limitations.'
    }
  }
}];

const items = $input.all();
if (!items.length) return [];
const webhook = $('Dataset Upload Webhook').first();
const body = webhook.json?.body ?? webhook.json ?? {};
function datasetId(){
  const supplied=String(body.dataset_id ?? body.dataset_session_id ?? '').trim();
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(supplied)) return supplied;
  const execId=String($execution.id ?? Date.now()).replace(/\\D/g,'').slice(-12).padStart(12,'0');
  return `00000000-0000-4000-8000-${execId}`;
}
function snake(name){let s=String(name??'').trim().replace(/([a-z0-9])([A-Z])/g,'$1_$2').replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_+|_+$/g,'').toLowerCase(); if(!s)s='column'; if(/^\\d/.test(s))s='col_'+s; return s;}
function norm(v){if(v==null)return null; if(typeof v!=='string')return v; const t=v.trim(); if(!t||['null','none','n/a','na','nan','undefined'].includes(t.toLowerCase()))return null; return t;}
function convert(v){v=norm(v); if(v===null)return null; if(typeof v!=='string')return v; const s=v.trim(), low=s.toLowerCase(); if(['true','yes','y'].includes(low))return true; if(['false','no','n'].includes(low))return false; if(!/^0\\d+$/.test(s)){const n=s.replace(/^\\$/,'').replace(/,/g,'').replace(/%$/,''); if(/^[-+]?(?:\\d+\\.?\\d*|\\.\\d+)$/.test(n)){const x=Number(n); if(Number.isFinite(x))return x;}} const looks=/^\\d{4}[-/]\\d{1,2}[-/]\\d{1,2}/.test(s)||/^\\d{1,2}[-/]\\d{1,2}[-/]\\d{2,4}/.test(s)||/^\\d{4}-\\d{2}-\\d{2}T/.test(s); if(looks){const ms=Date.parse(s); if(!Number.isNaN(ms))return new Date(ms).toISOString();} return s;}
const id=datasetId(); const batchNo=($runIndex??0)+1; const source=items.map(i=>i.json??{}); const cols=Object.keys(source[0]??{}); const map={}; const used=new Set(); for(const c of cols){let b=snake(c),n=b,k=2; while(used.has(n))n=`${b}_${k++}`; used.add(n); map[c]=n;}
const profile={}; for(const c of cols){const n=map[c]; profile[n]={original_name:c,column_name:n,null_count:0,non_null_count:0,numeric_count:0,boolean_count:0,timestamp_count:0,numeric_sum:0,numeric_min:null,numeric_max:null,sample_values:[]};}
const seen=new Set(), rows=[]; let dup=0;
for(const raw of source){const clean={}; for(const c of cols){const n=map[c],v=convert(raw[c]),p=profile[n]; clean[n]=v; if(v==null){p.null_count++; continue;} p.non_null_count++; if(typeof v==='number'){p.numeric_count++; p.numeric_sum+=v; p.numeric_min=p.numeric_min===null?v:Math.min(p.numeric_min,v); p.numeric_max=p.numeric_max===null?v:Math.max(p.numeric_max,v);} else if(typeof v==='boolean')p.boolean_count++; else if(typeof v==='string'&&/^\\d{4}-\\d{2}-\\d{2}T/.test(v))p.timestamp_count++; if(p.sample_values.length<6 && !p.sample_values.some(x=>String(x)===String(v)))p.sample_values.push(v);} const key=JSON.stringify(clean); if(seen.has(key)){dup++; continue;} seen.add(key); rows.push({raw_data:raw,clean_data:clean});}
return [{json:{dataset_id:id,dataset_name:body.dataset_name||body.original_filename||'dataset',original_filename:body.original_filename||body.dataset_name||'dataset.csv',user_id:body.user_id??null,organization_id:body.organization_id??null,batch_no:batchNo,source_row_count:source.length,clean_row_count:rows.length,duplicate_rows_removed:dup,rows,batch_profile:Object.values(profile)}}];

const d=$json; function q(v){if(v==null)return 'NULL'; return `'${String(v).replace(/'/g,"''")}'`;} function j(v){return `${q(JSON.stringify(v))}::jsonb`;}
const base=(Number(d.batch_no)-1)*500;
const vals=(d.rows||[]).map((r,i)=>`(${q(d.dataset_id)}::uuid,${base+i+1},${j(r.raw_data)},${j(r.clean_data)})`).join(',');
const sql=`
CREATE TABLE IF NOT EXISTS public.dealos_datasets (id uuid PRIMARY KEY, organization_id text, user_id text, name text NOT NULL, original_filename text, row_count_raw integer NOT NULL DEFAULT 0, row_count_clean integer NOT NULL DEFAULT 0, column_count integer NOT NULL DEFAULT 0, quality_score numeric, domain text, grain_description text, grain_confidence text, status text NOT NULL DEFAULT 'processing', profile_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dealos_dataset_rows (dataset_id uuid NOT NULL REFERENCES public.dealos_datasets(id) ON DELETE CASCADE,row_number bigint NOT NULL,raw_data jsonb NOT NULL,clean_data jsonb NOT NULL,PRIMARY KEY(dataset_id,row_number));
CREATE TABLE IF NOT EXISTS public.dealos_profile_batches (dataset_id uuid NOT NULL REFERENCES public.dealos_datasets(id) ON DELETE CASCADE,batch_no integer NOT NULL,source_row_count integer NOT NULL DEFAULT 0,clean_row_count integer NOT NULL DEFAULT 0,duplicate_rows_removed integer NOT NULL DEFAULT 0,profile_json jsonb NOT NULL,PRIMARY KEY(dataset_id,batch_no));
INSERT INTO public.dealos_datasets(id,organization_id,user_id,name,original_filename,status) VALUES(${q(d.dataset_id)}::uuid,${q(d.organization_id)},${q(d.user_id)},${q(d.dataset_name)},${q(d.original_filename)},'processing') ON CONFLICT(id) DO NOTHING;
${vals?`INSERT INTO public.dealos_dataset_rows(dataset_id,row_number,raw_data,clean_data) VALUES ${vals} ON CONFLICT(dataset_id,row_number) DO UPDATE SET raw_data=EXCLUDED.raw_data, clean_data=EXCLUDED.clean_data;`:''}
INSERT INTO public.dealos_profile_batches(dataset_id,batch_no,source_row_count,clean_row_count,duplicate_rows_removed,profile_json) VALUES(${q(d.dataset_id)}::uuid,${Number(d.batch_no)},${Number(d.source_row_count||0)},${Number(d.clean_row_count||0)},${Number(d.duplicate_rows_removed||0)},${j(d.batch_profile)}) ON CONFLICT(dataset_id,batch_no) DO UPDATE SET source_row_count=EXCLUDED.source_row_count,clean_row_count=EXCLUDED.clean_row_count,duplicate_rows_removed=EXCLUDED.duplicate_rows_removed,profile_json=EXCLUDED.profile_json;`;
return [{json:{dataset_id:d.dataset_id,sql}}];

const counts = $('Get Final Dataset Counts').first().json;
const batchRows = $input.all().map(item => item.json);

if (!counts) {
  throw new Error('Get Final Dataset Counts returned no data');
}

const rowCountRaw = Number(counts.row_count_raw ?? 0);
const rowCountClean = Number(counts.row_count_clean ?? 0);

if (!batchRows.length) {
  throw new Error('No batch profile rows received');
}

const firstBatch = $('Clean Current Batch').first().json;

const columns = {};
const cleaningActions = {};

let duplicateRowsRemoved = 0;

// --------------------------------------------------
// Aggregate batch profiles
// --------------------------------------------------

for (const batch of batchRows) {
  duplicateRowsRemoved += Number(
    batch.duplicate_rows_removed ?? 0
  );

  let profile = batch.profile_json;

  if (typeof profile === 'string') {
    try {
      profile = JSON.parse(profile);
    } catch {
      profile = [];
    }
  }

  if (!Array.isArray(profile)) {
    profile = [];
  }

  for (const p of profile) {
    if (!p?.column_name) continue;

    const name = p.column_name;

    if (!columns[name]) {
      columns[name] = {
        original_name: p.original_name ?? name,
        column_name: name,

        null_count: 0,
        non_null_count: 0,

        numeric_count: 0,
        boolean_count: 0,
        timestamp_count: 0,

        numeric_sum: 0,
        numeric_min: null,
        numeric_max: null,

        sample_values: []
      };
    }

    const c = columns[name];

    c.null_count += Number(p.null_count ?? 0);
    c.non_null_count += Number(p.non_null_count ?? 0);

    c.numeric_count += Number(p.numeric_count ?? 0);
    c.boolean_count += Number(p.boolean_count ?? 0);
    c.timestamp_count += Number(p.timestamp_count ?? 0);

    c.numeric_sum += Number(p.numeric_sum ?? 0);

    if (
      p.numeric_min !== null &&
      p.numeric_min !== undefined
    ) {
      const value = Number(p.numeric_min);

      c.numeric_min =
        c.numeric_min === null
          ? value
          : Math.min(c.numeric_min, value);
    }

    if (
      p.numeric_max !== null &&
      p.numeric_max !== undefined
    ) {
      const value = Number(p.numeric_max);

      c.numeric_max =
        c.numeric_max === null
          ? value
          : Math.max(c.numeric_max, value);
    }

    const samples = Array.isArray(p.sample_values)
      ? p.sample_values
      : [];

    for (const value of samples) {
      if (c.sample_values.length >= 8) break;

      const serialized =
        typeof value === 'object'
          ? JSON.stringify(value)
          : String(value);

      const exists = c.sample_values.some(existing => {
        const existingSerialized =
          typeof existing === 'object'
            ? JSON.stringify(existing)
            : String(existing);

        return existingSerialized === serialized;
      });

      if (!exists) {
        c.sample_values.push(value);
      }
    }
  }

  // --------------------------------------------------
  // Cleaning log aggregation
  // --------------------------------------------------

  let logs = batch.cleaning_log;

  if (typeof logs === 'string') {
    try {
      logs = JSON.parse(logs);
    } catch {
      logs = [];
    }
  }

  if (!Array.isArray(logs)) {
    logs = [];
  }

  for (const log of logs) {
    if (!log?.action) continue;

    const key = log.action;

    if (!cleaningActions[key]) {
      cleaningActions[key] = {
        action: key,
        rows_affected: 0,
        automatic: log.automatic !== false
      };
    }

    cleaningActions[key].rows_affected += Number(
      log.rows_affected ?? 0
    );
  }
}

// --------------------------------------------------
// Build final column profiles
// --------------------------------------------------

const columnProfiles = Object.values(columns).map(c => {
  const nonNull = c.non_null_count || 1;

  let detectedType = 'text';

  if (c.boolean_count / nonNull >= 0.98) {
    detectedType = 'boolean';
  } else if (
    c.timestamp_count / nonNull >= 0.95
  ) {
    detectedType = 'timestamp';
  } else if (
    c.numeric_count / nonNull >= 0.98
  ) {
    detectedType = 'numeric';
  }

  const nullPct =
    rowCountClean > 0
      ? Number(
          (
            (c.null_count * 100) /
            rowCountClean
          ).toFixed(2)
        )
      : 0;

  return {
    original_name: c.original_name,
    column_name: c.column_name,

    detected_type: detectedType,

    null_count: c.null_count,
    null_pct: nullPct,

    unique_count: null,
    unique_count_capped: true,

    min_value: c.numeric_min,
    max_value: c.numeric_max,

    mean_value:
      c.numeric_count > 0
        ? c.numeric_sum / c.numeric_count
        : null,

    sample_values: c.sample_values
  };
});

// --------------------------------------------------
// Quality score
// --------------------------------------------------

const totalCells =
  Math.max(
    rowCountClean *
      Math.max(columnProfiles.length, 1),
    1
  );

const missingCells = columnProfiles.reduce(
  (sum, column) =>
    sum + Number(column.null_count ?? 0),
  0
);

const missingPct =
  (missingCells * 100) / totalCells;

const duplicatePct =
  rowCountRaw > 0
    ? (duplicateRowsRemoved * 100) /
      rowCountRaw
    : 0;

const qualityScore = Math.max(
  0,
  Math.min(
    100,
    Math.round(
      100 -
        missingPct * 0.35 -
        duplicatePct * 0.65
    )
  )
);

// --------------------------------------------------
// Quality issues
// --------------------------------------------------

const qualityIssues = [];

for (const column of columnProfiles) {
  if (column.null_pct >= 20) {
    qualityIssues.push({
      issue_type: 'high_missingness',
      column_name: column.column_name,
      severity:
        column.null_pct >= 50
          ? 'high'
          : 'medium',
      details:
        `${column.null_pct}% of values are missing`
    });
  }
}

if (duplicateRowsRemoved > 0) {
  qualityIssues.push({
    issue_type: 'exact_duplicates',
    column_name: null,
    severity:
      duplicatePct >= 5
        ? 'high'
        : 'medium',
    details:
      `${duplicateRowsRemoved} duplicate rows were removed`
  });
}

// --------------------------------------------------
// Final profile for AI
// --------------------------------------------------

const profileForAI = {
  dataset_id: firstBatch.dataset_id,

  dataset_name:
    firstBatch.dataset_name ??
    firstBatch.original_filename ??
    'Dataset',

  original_filename:
    firstBatch.original_filename ??
    firstBatch.dataset_name ??
    null,

  row_count_raw: rowCountRaw,
  row_count_clean: rowCountClean,

  column_count: columnProfiles.length,

  quality_score: qualityScore,

  columns: columnProfiles,

  quality_issues: qualityIssues,

  cleaning_log:
    Object.values(cleaningActions),

  sample_rows: []
};

// --------------------------------------------------
// Return final dataset profile
// --------------------------------------------------

return [{
  json: {
    dataset_id: firstBatch.dataset_id,

    dataset_name:
      firstBatch.dataset_name ??
      firstBatch.original_filename ??
      'Dataset',

    original_filename:
      firstBatch.original_filename ??
      firstBatch.dataset_name ??
      null,

    user_id:
      firstBatch.user_id ?? null,

    organization_id:
      firstBatch.organization_id ?? null,

    row_count_raw: rowCountRaw,
    row_count_clean: rowCountClean,

    column_count: columnProfiles.length,

    quality_score: qualityScore,

    duplicate_rows_removed:
      duplicateRowsRemoved,

    column_profiles: columnProfiles,

    quality_issues: qualityIssues,

    cleaning_log:
      Object.values(cleaningActions),

    profile_for_ai: profileForAI
  }
}];

const body = $json.body ?? $json;

const bucket = String(body.storage_bucket ?? 'analyzeros-datasets').trim();
const path = String(body.storage_path ?? '').trim();

if (!bucket) throw new Error('storage_bucket is required');
if (!path) throw new Error('storage_path is required');

return [{
  json: {
    storage_bucket: bucket,
    storage_path: path,
    dataset_name: body.dataset_name ?? body.original_filename ?? path.split('/').pop(),
    original_filename: body.original_filename ?? path.split('/').pop(),
    file_size: body.file_size ?? null,
    dataset_session_id: body.dataset_session_id ?? null,
    user_id: body.user_id ?? null,
    organization_id: body.organization_id ?? null
  }
}];

const rows = $input.all();

if (!rows.length) {
  throw new Error('CSV produced no rows');
}

const keys = Object.keys(rows[0].json ?? {});
const suspicious = [
  'headers',
  'body',
  'params',
  'query',
  'webhookUrl',
  'webhook_url'
];

const suspiciousCount = suspicious.filter(k => keys.includes(k)).length;

if (suspiciousCount >= 2) {
  throw new Error(
    'AnalyzerOS detected upload metadata instead of dataset contents. Check the Supabase download and Extract CSV nodes.'
  );
}

return rows;
